import { test, expect } from '@playwright/test';

test.describe('File Upload Queue Management', () => {
  let uploadPage: string;

  test.beforeEach(async ({ page }) => {
    uploadPage = 'data:text/html,<html><body><div id="upload-container"><input type="file" id="file-input" multiple /><div id="queue-list"></div><button id="submit-btn">Submit</button></div><script>const fileInput = document.getElementById("file-input"); const queueList = document.getElementById("queue-list"); const submitBtn = document.getElementById("submit-btn"); let uploadQueue = []; fileInput.addEventListener("change", (e) => { const files = Array.from(e.target.files); files.forEach((file, index) => { uploadQueue.push({name: file.name, id: Math.random()}); renderQueue(); }); }); function renderQueue() { queueList.innerHTML = ""; uploadQueue.forEach((file, index) => { const item = document.createElement("div"); item.className = "queue-item"; item.innerHTML = `<span>${file.name}</span><button class="remove-btn" data-id="${file.id}">Remove</button>`; queueList.appendChild(item); }); } document.addEventListener("click", (e) => { if (e.target.classList.contains("remove-btn")) { const fileId = e.target.getAttribute("data-id"); uploadQueue = uploadQueue.filter(f => f.id != fileId); renderQueue(); } }); submitBtn.addEventListener("click", () => { alert("Submitting " + uploadQueue.length + " files"); }); </script></body></html>';
    await page.goto(uploadPage);
  });

  test('should display uploaded files in queue', async ({ page }) => {
    const fileInput = page.locator('#file-input');

    // Create test files
    await fileInput.setInputFiles([
      { name: 'test1.txt', mimeType: 'text/plain', buffer: Buffer.from('test content 1') },
      { name: 'test2.pdf', mimeType: 'application/pdf', buffer: Buffer.from('test content 2') }
    ]);

    // Verify files appear in queue
    const queueItems = page.locator('.queue-item');
    await expect(queueItems).toHaveCount(2);

    // Verify file names are displayed
    await expect(page.getByText('test1.txt')).toBeVisible();
    await expect(page.getByText('test2.pdf')).toBeVisible();
  });

  test('should remove a single file from queue', async ({ page }) => {
    const fileInput = page.locator('#file-input');

    // Add multiple files
    await fileInput.setInputFiles([
      { name: 'document1.txt', mimeType: 'text/plain', buffer: Buffer.from('content 1') },
      { name: 'document2.txt', mimeType: 'text/plain', buffer: Buffer.from('content 2') },
      { name: 'document3.txt', mimeType: 'text/plain', buffer: Buffer.from('content 3') }
    ]);

    // Verify all files are in queue
    const queueItems = page.locator('.queue-item');
    await expect(queueItems).toHaveCount(3);

    // Remove the middle file
    const removeButtons = page.locator('button.remove-btn');
    await removeButtons.nth(1).click();

    // Verify only 2 files remain
    await expect(queueItems).toHaveCount(2);

    // Verify correct files remain
    await expect(page.getByText('document1.txt')).toBeVisible();
    await expect(page.getByText('document3.txt')).toBeVisible();
    await expect(page.getByText('document2.txt')).not.toBeVisible();
  });

  test('should remove all files from queue one by one', async ({ page }) => {
    const fileInput = page.locator('#file-input');

    // Add files
    await fileInput.setInputFiles([
      { name: 'file1.txt', mimeType: 'text/plain', buffer: Buffer.from('content 1') },
      { name: 'file2.txt', mimeType: 'text/plain', buffer: Buffer.from('content 2') }
    ]);

    // Verify files are in queue
    let queueItems = page.locator('.queue-item');
    await expect(queueItems).toHaveCount(2);

    // Remove first file
    let removeButtons = page.locator('button.remove-btn');
    await removeButtons.first().click();

    // Verify one file remains
    await expect(queueItems).toHaveCount(1);
    await expect(page.getByText('file2.txt')).toBeVisible();

    // Remove second file
    removeButtons = page.locator('button.remove-btn');
    await removeButtons.first().click();

    // Verify queue is empty
    await expect(queueItems).toHaveCount(0);
  });

  test('should prevent submission when queue is empty after removing all files', async ({ page }) => {
    const fileInput = page.locator('#file-input');

    // Add a file
    await fileInput.setInputFiles([
      { name: 'test.txt', mimeType: 'text/plain', buffer: Buffer.from('test') }
    ]);

    // Remove the file
    const removeButton = page.locator('button.remove-btn');
    await removeButton.click();

    // Verify queue is empty
    const queueItems = page.locator('.queue-item');
    await expect(queueItems).toHaveCount(0);

    // Set up listener for alert
    page.once('dialog', dialog => {
      expect(dialog.message()).toContain('Submitting 0 files');
      dialog.accept();
    });

    // Try to submit
    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();
  });

  test('should maintain queue state after removing and adding new files', async ({ page }) => {
    const fileInput = page.locator('#file-input');

    // Add initial files
    await fileInput.setInputFiles([
      { name: 'initial1.txt', mimeType: 'text/plain', buffer: Buffer.from('content 1') },
      { name: 'initial2.txt', mimeType: 'text/plain', buffer: Buffer.from('content 2') }
    ]);

    // Remove one file
    const removeButton = page.locator('button.remove-btn').first();
    await removeButton.click();

    // Verify state
    let queueItems = page.locator('.queue-item');
    await expect(queueItems).toHaveCount(1);
    await expect(page.getByText('initial2.txt')).toBeVisible();

    // Add new files
    await fileInput.setInputFiles([
      { name: 'new1.txt', mimeType: 'text/plain', buffer: Buffer.from('new content 1') },
      { name: 'new2.txt', mimeType: 'text/plain', buffer: Buffer.from('new content 2') }
    ]);

    // Verify queue now has 3 files (1 remaining + 2 new)
    queueItems = page.locator('.queue-item');
    await expect(queueItems).toHaveCount(3);
    await expect(page.getByText('initial2.txt')).toBeVisible();
    await expect(page.getByText('new1.txt')).toBeVisible();
    await expect(page.getByText('new2.txt')).toBeVisible();
  });
});
